CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('OWNER','CONTENT_MANAGER','VIEWER')), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS records(kind TEXT NOT NULL, slug TEXT NOT NULL, draft TEXT NOT NULL, live TEXT, state TEXT NOT NULL, source TEXT NOT NULL, verified TEXT NOT NULL, revision INTEGER NOT NULL, PRIMARY KEY(kind, slug));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, dt TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, previous TEXT, next TEXT);
PRAGMA user_version=1;
CREATE TABLE IF NOT EXISTS media(id TEXT PRIMARY KEY, png BLOB NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL);
